// Micropolis scenarios / Micropolis 剧本 — eight original towns with a
// public premise each, made by AI System 6.
//
// Nothing here comes from a Maxis scenario file: every map is generated by
// the engine's MapGenerator from our own seed, the starting town is laid by
// our own seeder through the engine's public tools, and the names are ours.
// The premises (a dull town, a quake, a firestorm, a traffic jam, a monster,
// a crime wave, a flood, a pollution crisis) are public facts about the
// classic game, not its data.
window.AISystem6MicropolisScenariosLoaded = true;

(function initMicropolisScenarios() {
  "use strict";

  const TICKS_PER_MONTH = 4;
  const TICKS_PER_YEAR = 48;

  // id, starting year, terrain seed, difficulty, treasury, town preset,
  // scripted triggers (months after the start), and the goal with its deadline.
  const SCENARIOS = Object.freeze([
    { id: "quietwater", year: 1900, seed: 0x51e7a001, level: 0, funds: 20000, town: "medium", triggers: [],
      goal: { kind: "population", value: 4000, years: 10 } },
    { id: "faultline", year: 1906, seed: 0xfa17a906, level: 1, funds: 20000, town: "large",
      triggers: [{ atMonths: 1, disaster: "earthquake" }], goal: { kind: "population", value: 6000, years: 5 } },
    { id: "ashford", year: 1944, seed: 0xa5f0d944, level: 1, funds: 20000, town: "large",
      triggers: [1, 2, 3, 4, 5].map((month) => ({ atMonths: month, disaster: "fire" })), goal: { kind: "population", value: 6000, years: 5 } },
    { id: "gridlock", year: 1965, seed: 0x6d1d1965, level: 1, funds: 20000, town: "large", triggers: [],
      goal: { kind: "traffic", value: 40, years: 10 } },
    { id: "marrowbay", year: 1957, seed: 0x3a22b957, level: 0, funds: 20000, town: "medium",
      triggers: [{ atMonths: 1, disaster: "monster" }], goal: { kind: "population", value: 4000, years: 5 } },
    { id: "harbourheights", year: 1972, seed: 0x4a2b0972, level: 2, funds: 20000, town: "large", triggers: [],
      goal: { kind: "crime", value: 60, years: 10 } },
    { id: "riverbend", year: 2010, seed: 0x21ec2010, level: 0, funds: 20000, town: "medium",
      triggers: [{ atMonths: 1, disaster: "flood" }], goal: { kind: "population", value: 3000, years: 5 } },
    { id: "smokestack", year: 2047, seed: 0x5a0c2047, level: 2, funds: 20000, town: "large", triggers: [],
      goal: { kind: "pollution", value: 60, years: 10 } },
  ]);

  // Town presets: blocks of 3x3 zones on a road grid with a pitch of four.
  const TOWN_PRESETS = Object.freeze({
    small: { cols: 3, rows: 2 },
    medium: { cols: 5, rows: 3 },
    large: { cols: 6, rows: 4 },
  });
  const BLOCK_PITCH = 4;
  const PLANT_APRON = 6; // room for the 4x4 coal plant to the right of the grid

  function scenarioById(id) {
    return SCENARIOS.find((scenario) => scenario.id === id) || null;
  }

  // Pure: the footprint a preset needs, in tiles.
  function townFootprint(preset) {
    return { width: preset.cols * BLOCK_PITCH + 1 + PLANT_APRON, height: preset.rows * BLOCK_PITCH + 1 };
  }

  function isWater(engine, value) {
    const TV = engine.TileValues;
    return value >= TV.RIVER && value <= TV.LASTRIVEDGE;
  }

  // Pure over the map: the origin of the window with the most dry tiles.
  function findTownOrigin(engine, map, preset) {
    const { width, height } = townFootprint(preset);
    let best = { x: 2, y: 2, dry: -1 };
    for (let oy = 2; oy + height < map.height - 2; oy += 2) {
      for (let ox = 2; ox + width < map.width - 2; ox += 2) {
        let dry = 0;
        for (let y = oy; y < oy + height; y += 1) {
          for (let x = ox; x < ox + width; x += 1) {
            if (!isWater(engine, map.getTileValue(x, y))) dry += 1;
          }
        }
        if (dry > best.dry) best = { x: ox, y: oy, dry };
      }
    }
    return best;
  }

  // Zone kind per block: two residential, one commercial, one industrial.
  function zoneKindFor(col, row) {
    return ["residential", "residential", "commercial", "industrial"][(col + row) % 4];
  }

  // Lays the starting town through the engine's own tools with a temporary
  // treasury, then restores funds and the auto-bulldoze setting. Returns a
  // tally so a caller (or a test) can see what actually landed.
  function seedTown(engine, map, sim, presetName) {
    const preset = TOWN_PRESETS[presetName] || TOWN_PRESETS.medium;
    const origin = findTownOrigin(engine, map, preset);
    const tools = engine.createTools(map);
    const budget = sim.budget;
    const savedFunds = budget.totalFunds;
    const savedAutoBulldoze = engine.BaseTool.getAutoBulldoze();
    budget.totalFunds = 1e9;
    engine.BaseTool.setAutoBulldoze(true);
    const tally = { origin, roads: 0, wires: 0, zones: 0, plant: false };
    const apply = (tool, x, y) => {
      if (!map.testBounds(x, y)) return false;
      tool.doTool(x, y, sim.blockMaps);
      tool.modifyIfEnoughFunding(budget);
      return tool.result === tool.TOOLRESULT_OK;
    };
    try {
      const right = origin.x + preset.cols * BLOCK_PITCH;
      const bottom = origin.y + preset.rows * BLOCK_PITCH;
      for (let row = 0; row <= preset.rows; row += 1) {
        for (let x = origin.x; x <= right; x += 1) if (apply(tools.road, x, origin.y + row * BLOCK_PITCH)) tally.roads += 1;
      }
      for (let col = 0; col <= preset.cols; col += 1) {
        for (let y = origin.y; y <= bottom; y += 1) if (apply(tools.road, origin.x + col * BLOCK_PITCH, y)) tally.roads += 1;
      }
      // Power runs along every horizontal road (road-and-wire crossings);
      // zones touching those tiles conduct.
      for (let row = 0; row <= preset.rows; row += 1) {
        for (let x = origin.x; x <= right; x += 1) if (apply(tools.wire, x, origin.y + row * BLOCK_PITCH)) tally.wires += 1;
      }
      for (let row = 0; row < preset.rows; row += 1) {
        for (let col = 0; col < preset.cols; col += 1) {
          const kind = zoneKindFor(col, row);
          if (apply(tools[kind], origin.x + col * BLOCK_PITCH + 2, origin.y + row * BLOCK_PITCH + 2)) tally.zones += 1;
        }
      }
      // The coal plant sits just right of the grid, touching the top road.
      tally.plant = apply(tools.coal, right + 2, origin.y + 1);
    } finally {
      budget.totalFunds = savedFunds;
      engine.BaseTool.setAutoBulldoze(savedAutoBulldoze);
    }
    return tally;
  }

  // --- running state -----------------------------------------------------------

  function createState(scenario, cityTime) {
    return { id: scenario.id, startTime: cityTime, fired: [], result: "" };
  }

  // Pure: trigger indices due at this elapsed time that have not fired.
  function dueTriggers(scenario, elapsedTicks, fired) {
    return scenario.triggers
      .map((trigger, index) => ({ trigger, index }))
      .filter(({ trigger, index }) => elapsedTicks >= trigger.atMonths * TICKS_PER_MONTH && !fired.includes(index))
      .map(({ index }) => index);
  }

  // Pure over the simulation: the number the goal is measured on.
  function measure(sim, kind) {
    if (kind === "population") return sim.evaluation.cityPop || 0;
    if (kind === "crime") return sim._census.crimeAverage || 0;
    if (kind === "pollution") return sim._census.pollutionAverage || 0;
    if (kind === "traffic") {
      const blockMap = sim.blockMaps.trafficDensityMap;
      let total = 0;
      let count = 0;
      for (let y = 0; y < sim._map.height; y += blockMap.blockSize) {
        for (let x = 0; x < sim._map.width; x += blockMap.blockSize) {
          total += blockMap.worldGet(x, y);
          count += 1;
        }
      }
      return count ? Math.round(total / count) : 0;
    }
    return 0;
  }

  // Pure: "won", "lost", or "" for still running. A population goal wins
  // the moment it is reached; a "keep it below" goal is judged at the deadline.
  function judge(scenario, value, elapsedTicks) {
    const goal = scenario.goal;
    const met = goal.kind === "population" ? value >= goal.value : value <= goal.value;
    if (goal.kind === "population" && met) return "won";
    if (elapsedTicks >= goal.years * TICKS_PER_YEAR) return met ? "won" : "lost";
    return "";
  }

  // One step: returns the disasters to fire now and updates the state.
  function tick(sim, state) {
    const scenario = scenarioById(state.id);
    if (!scenario || state.result) return { disasters: [], result: state.result };
    const elapsed = sim._cityTime - state.startTime;
    const due = dueTriggers(scenario, elapsed, state.fired);
    state.fired.push(...due);
    state.result = judge(scenario, measure(sim, scenario.goal.kind), elapsed);
    return { disasters: due.map((index) => scenario.triggers[index].disaster), result: state.result };
  }

  function progress(sim, state) {
    const scenario = scenarioById(state.id);
    if (!scenario) return null;
    const elapsed = sim._cityTime - state.startTime;
    return {
      value: measure(sim, scenario.goal.kind),
      target: scenario.goal.value,
      kind: scenario.goal.kind,
      yearsLeft: Math.max(0, Math.ceil((scenario.goal.years * TICKS_PER_YEAR - elapsed) / TICKS_PER_YEAR)),
      result: state.result,
    };
  }

  window.AISystem6MicropolisScenarios = Object.freeze({
    SCENARIOS,
    TOWN_PRESETS,
    TICKS_PER_MONTH,
    TICKS_PER_YEAR,
    scenarioById,
    townFootprint,
    findTownOrigin,
    zoneKindFor,
    seedTown,
    createState,
    dueTriggers,
    measure,
    judge,
    tick,
    progress,
  });
})();
